type Def = Omit<Intent, 'kind' | 'topic'> & { kind?: Intent['kind']; topic?: string };

const group = (topic: string, kind: Intent['kind'], defs: Def[]): Intent[] =>
  defs.map((def) => ({ ...def, kind: def.kind ?? kind, topic: def.topic ?? topic }));

